import hashlib
import json


class KeyConflict(Exception):
    pass


def fingerprint(method, path, body):
    text = json.dumps([method.upper(), path, body], sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


class IdempotencyStore:
    def __init__(self, clock, ttl=86400):
        self.clock = clock
        self.ttl = ttl
        self.entries = {}

    def run(self, key, request_fingerprint, operation):
        now = self.clock()
        self.entries = {k: e for k, e in self.entries.items() if now < e[2] + self.ttl}
        if key is None:
            return (operation(), False)
        if key in self.entries:
            stored_fingerprint, result, _ = self.entries[key]
            if stored_fingerprint != request_fingerprint:
                raise KeyConflict(f"idempotency key {key!r} was used for a different request")
            return (result, True)
        result = operation()
        self.entries[key] = (request_fingerprint, result, now)
        return (result, False)


class Deadline:
    def __init__(self, total, clock):
        self.clock = clock
        self.end = clock() + total

    def remaining(self):
        return max(0, self.end - self.clock())

    def timeout(self, longest):
        left = self.remaining()
        if left <= 0:
            raise TimeoutError("the deadline has passed")
        return min(longest, left)

