class Clock:
    def __init__(self, t=0):
        self.t = t
    def __call__(self):
        return self.t

class Payments:
    def __init__(self):
        self.made = 0
    def __call__(self):
        self.made += 1
        return {"payment": self.made}

@test("fingerprints")
def _():
    a = fingerprint("post", "/v1/payments", {"amount": 1999, "currency": "EUR"})
    b = fingerprint("POST", "/v1/payments", {"currency": "EUR", "amount": 1999})
    check_eq(a, b)
    check_eq(len(a), 64)
    check(a != fingerprint("POST", "/v1/payments", {"amount": 2000, "currency": "EUR"}))
    check(a != fingerprint("POST", "/v1/refunds", {"amount": 1999, "currency": "EUR"}))

@test("a retry is replayed, not repeated")
def _():
    store, pay = IdempotencyStore(Clock()), Payments()
    fp = fingerprint("POST", "/v1/payments", {"amount": 1})
    check_eq(store.run("k1", fp, pay), ({"payment": 1}, False))
    check_eq(store.run("k1", fp, pay), ({"payment": 1}, True))
    check_eq(pay.made, 1)
    check_eq(store.run("k2", fp, pay), ({"payment": 2}, False))

@test("a reused key with other content")
def _():
    store, pay = IdempotencyStore(Clock()), Payments()
    store.run("k1", fingerprint("POST", "/p", {"amount": 1}), pay)
    check_raises(KeyConflict, store.run, "k1", fingerprint("POST", "/p", {"amount": 2}), pay)
    check_eq(pay.made, 1)

@test("no key, and failures")
def _():
    store, pay = IdempotencyStore(Clock()), Payments()
    check_eq(store.run(None, "x", pay), ({"payment": 1}, False))
    check_eq(store.run(None, "x", pay), ({"payment": 2}, False))
    def boom():
        raise RuntimeError("card declined")
    check_raises(RuntimeError, store.run, "k9", "fp", boom)
    check_eq(store.run("k9", "fp", pay), ({"payment": 3}, False))

@test("keys expire")
def _():
    clock = Clock(100)
    store, pay = IdempotencyStore(clock, ttl=60), Payments()
    store.run("k", "fp", pay)
    clock.t = 159
    check_eq(store.run("k", "fp", pay), ({"payment": 1}, True))
    clock.t = 160
    check_eq(store.run("k", "fp", pay), ({"payment": 2}, False))

@test("deadlines")
def _():
    clock = Clock(10)
    d = Deadline(30, clock)
    check_eq(d.remaining(), 30)
    check_eq(d.timeout(10), 10)
    clock.t = 35
    check_eq(d.timeout(10), 5)
    clock.t = 40
    check_eq(d.remaining(), 0)
    check_raises(TimeoutError, d.timeout, 10)
    clock.t = 50
    check_eq(d.remaining(), 0)

